CREATE OR REPLACE FUNCTION fn_purgar_historial_antiguo(p_dias_antiguedad INT DEFAULT 90) RETURNS INT AS $$ DECLARE v_filas_eliminadas INT; BEGIN -- Paso 1: archivar en estadistica_ambiental (periodo 'mensual') -- antes de borrar el detalle. Si esto falla, no se borra nada. INSERT INTO estadistica_ambiental (id_aula, id_variable, periodo, valor_promedio, valor_minimo, valor_maximo, fecha_inicio, fecha_fin, fecha_calculo) SELECT s.id_aula, cv.id_variable, 'mensual', AVG(hv.valor), MIN(hv.valor), MAX(hv.valor), date_trunc('month', hv.fecha_hora_lectura), date_trunc('month', hv.fecha_hora_lectura) + INTERVAL '1 month' - INTERVAL '1 second', now() FROM historial_variable hv JOIN configuracion_variable cv ON cv.id_configuracion = hv.id_configuracion JOIN sensor s ON s.id_sensor = cv.id_sensor WHERE hv.fecha_hora_lectura < now() - (p_dias_antiguedad || ' days')::INTERVAL GROUP BY s.id_aula, cv.id_variable, date_trunc('month', hv.fecha_hora_lectura);
-- Paso 2: eliminar el detalle ya archivado. DELETE FROM historial_variable WHERE fecha_hora_lectura < now() - (p_dias_antiguedad || ' days')::INTERVAL;
GET DIAGNOSTICS v_filas_eliminadas = ROW_COUNT;
-- COMMIT implícito: ambos pasos quedan confirmados juntos. RETURN v_filas_eliminadas; EXCEPTION WHEN OTHERS THEN -- ROLLBACK automático: ni se archiva ni se borra nada. RAISE; END; $$ LANGUAGE plpgsql;
